drop view if exists public.public_marketplace_products; drop view if exists public.public_marketplace_stores;
create policy stores_public_verified_read on public.stores for select to anon,authenticated using(store_status='active' and verification_status='verified');
create policy products_public_verified_read on public.products for select to anon,authenticated using(status='published' and exists(select 1 from public.stores s where s.id=products.store_id and s.store_status='active' and s.verification_status='verified'));
create policy variants_public_verified_read on public.product_variants for select to anon,authenticated using(is_active=true and exists(select 1 from public.products p join public.stores s on s.id=p.store_id where p.id=product_variants.product_id and p.status='published' and s.store_status='active' and s.verification_status='verified'));
grant select(id,name,username,description,public_city,public_area,verification_status) on public.stores to anon,authenticated;
grant select(id,store_id,name,description,brand,base_unit,minimum_quantity,status) on public.products to anon,authenticated;
grant select(id,product_id,variant_name,sale_unit,online_price,discount_price,stock_quantity,is_active) on public.product_variants to anon,authenticated;
create view public.public_marketplace_stores with(security_invoker=true) as select s.id,s.name,s.username,s.description,s.public_city,s.public_area,s.verification_status from public.stores s where s.store_status='active' and s.verification_status='verified';
create view public.public_marketplace_products with(security_invoker=true) as select p.id,p.store_id,s.name as store_name,s.username as store_username,p.name,p.description,p.brand,p.base_unit,p.minimum_quantity,v.id as variant_id,v.variant_name,v.sale_unit,v.online_price,v.discount_price,v.stock_quantity from public.products p join public.stores s on s.id=p.store_id join public.product_variants v on v.product_id=p.id where p.status='published' and s.store_status='active' and s.verification_status='verified' and v.is_active=true and v.online_price is not null;
revoke all on public.public_marketplace_stores from anon,authenticated; revoke all on public.public_marketplace_products from anon,authenticated;
grant select on public.public_marketplace_stores to anon,authenticated; grant select on public.public_marketplace_products to anon,authenticated;